// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Ensure the market is seeded and initialized
        c.seedMarket{value: 1 ether}(100);
        // Call getFreeKilo() from the fuzzed address
        vm.prank(caller);
        c.getFreeKilo();
        // The rule: after getFreeKilo(), Kilos[caller] must equal 300
        assertTrue(c.Kilos(caller) == 300);
    }
}

